using System.Collections.Generic;using System.Text;public class Codec{public string Encode(IList<string>s){var r=new StringBuilder();foreach(var x in s)r.Append(x.Length).Append('#').Append(x);return r.ToString();}public IList<string> Decode(string s){var o=new List<string>();for(int i=0;i<s.Length;){int j=i;while(s[j]!='#')j++;int n=int.Parse(s.Substring(i,j-i));o.Add(s.Substring(j+1,n));i=j+1+n;}return o;}}
